import type { ExportJob } from "./export-job.js";

/** Classify the supplied media-export jobs before starting another export. */
export const canStartExport = (jobs: ReadonlyArray<ExportJob>): boolean =>
  jobs.filter(({ phase }) => phase === "working").length === 0;

import { Schema } from "effect";

/**
 * Phase and receipt settle independently. A non-null receipt finishes a job
 * even if phase is stale or null. A null receipt is unresolved for any phase.
 * The classifier only considers the rows supplied by its caller.
 */
export const ExportJob = Schema.Struct({
  id: Schema.Int.check(Schema.isGreaterThan(0)),
  phase: Schema.NullOr(Schema.Literals(["waiting", "working", "done"])),
  receipt: Schema.NullOr(Schema.Literals(["ok", "failed"])),
});
export type ExportJob = typeof ExportJob.Type;

